       ["command a", "op ;", "command b", "op &&", "command c", "op ||", "command d"])
expect("git status&&ls", ["command git", "op &&", "command ls"])
expect("echo hi\nls -l", ["command echo", "command ls", "flag -l"])
expect("ls \\\n -l", ["command ls", "flag -l"])
