    // Reading the pattern.
    func hexBytes(_ text: String) -> [UInt8]? { if case .success(let p) = SearchPattern.hex(text) { return p.bytes } else { return nil } }
    func hexWild(_ text: String) -> [Bool]? { if case .success(let p) = SearchPattern.hex(text) { return p.wildcard } else { return nil } }
    check(hexBytes("DE AD be ef") == [0xDE, 0xAD, 0xBE, 0xEF] && hexBytes("deadbeef") == [0xDE, 0xAD, 0xBE, 0xEF] && hexBytes("0xDE,0xAD;0xBE:0xEF") == [0xDE, 0xAD, 0xBE, 0xEF] && hexBytes("DE\nAD\tBE") == [0xDE, 0xAD, 0xBE], "hex is read with any spacing, commas, and 0x")
    check(hexBytes("0XDE 0xAD") == [0xDE, 0xAD], "0X is a prefix too")
    check(SearchPattern(bytes: [2, 3]).matches(in: [1, 2], at: 1) == false && SearchPattern(bytes: [2, 3]).matches(in: [1, 2, 3], at: -1) == false && SearchPattern(bytes: [2, 3]).matches(in: [1, 2, 3], at: 1) == true && SearchPattern(bytes: [2, 3]).matches(in: [], at: 0) == false, "a match must lie wholly inside the bytes")
    check(hexWild("DE ?? EF") == [false, true, false] && hexWild("DE ? EF") == [false, true, false] && hexWild("DE??EF") == [false, true, false] && hexBytes("DE ?? EF") == [0xDE, 0, 0xEF], "?? and ? stand for any byte")
    check(SearchPattern.hex("") == .failure(.empty) && SearchPattern.hex("  \n ") == .failure(.empty), "nothing to look for is said")
    check(SearchPattern.hex("DEA") == .failure(.oddDigits("DEA")) && SearchPattern.hex("D") == .failure(.oddDigits("D")), "an odd number of digits is said")
    check(SearchPattern.hex("GG") == .failure(.notHex("GG")) && SearchPattern.hex("DE ZZ") == .failure(.notHex("ZZ")) && SearchPattern.hex("DEZ") == .failure(.notHex("Z")) && SearchPattern.hex("D?") == .failure(.notHex("D?")), "what is not hex is said, and half a wildcard is not one")
    check(SearchPattern.hex(String(repeating: "AA ", count: 5000)) == .failure(.tooLong) && (try? SearchPattern.hex(String(repeating: "AA ", count: 4096)).get()) != nil, "4096 bytes is the most")
    check(SearchPattern.text("", encoding: .utf8, ignoresCase: false) == .failure(.empty) && SearchPattern.text("€", encoding: .latin1, ignoresCase: false) == .failure(.unencodable("€")) && SearchPattern.text(String(repeating: "a", count: 4097), encoding: .utf8, ignoresCase: false) == .failure(.tooLong), "text that cannot be searched for is said")
    func textBytes(_ text: String, _ encoding: SearchPattern.TextEncoding) -> [UInt8]? { if case .success(let p) = SearchPattern.text(text, encoding: encoding, ignoresCase: false) { return p.bytes } else { return nil } }
    check(textBytes("é€", .utf8) == [0xC3, 0xA9, 0xE2, 0x82, 0xAC] && textBytes("Ab", .utf16LittleEndian) == [0x41, 0, 0x62, 0] && textBytes("Ab", .utf16BigEndian) == [0, 0x41, 0, 0x62] && textBytes("é", .latin1) == [0xE9] && textBytes("😀", .utf16LittleEndian) == [0x3D, 0xD8, 0x00, 0xDE], "text is put in each encoding's bytes, surrogates included")
    check(SearchPattern.message(.empty).isEmpty == false && SearchPattern.message(.oddDigits("A")).contains("A") && SearchPattern.message(.notHex("Z")).contains("Z") && SearchPattern.message(.tooLong).contains("4096") && SearchPattern.message(.unencodable("€")).contains("€"), "every failure has words")
    check(SearchPattern.TextEncoding.allCases.allSatisfy { !$0.title.isEmpty }, "every encoding has a name")
    // Where a match may start.
    let small = DataByteSource([1, 2, 3, 2, 3, 4])
    let pattern = SearchPattern(bytes: [2, 3])
    func at(_ start: Int64, _ direction: SearchDirection, wraps: Bool = true) -> SearchOutcome { ByteSearcher.find(pattern, in: small, startingAt: start, direction: direction, wraps: wraps, chunk: 2) }
    check(at(0, .forward) == .found(1..<3) && at(1, .forward) == .found(1..<3) && at(2, .forward) == .found(3..<5) && at(3, .forward) == .found(3..<5), "going forward a match may start at where the search starts")
    check(at(4, .forward, wraps: false) == .notFound && at(4, .forward) == .found(1..<3), "past the last match, forward, it wraps to the first, or says there is none")
    check(at(5, .backward) == .found(3..<5) && at(3, .backward) == .found(3..<5) && at(2, .backward) == .found(1..<3) && at(1, .backward) == .found(1..<3), "going back a match may start at where the search starts")
    check(at(0, .backward, wraps: false) == .notFound && at(0, .backward) == .found(3..<5), "before the first match, backward, it wraps to the last, or says there is none")
    check(at(-5, .forward) == .found(1..<3) && at(1000, .forward) == .found(1..<3) && at(1000, .backward) == .found(3..<5) && at(-5, .backward) == .found(3..<5), "a start outside the file is brought inside")
    check(at(1000, .forward, wraps: false) == .notFound && at(-5, .backward, wraps: false) == .notFound, "and without wrapping there is nothing past the ends")
    check(ByteSearcher.find(SearchPattern(bytes: [1, 2, 3, 2, 3, 4, 5]), in: small, startingAt: 0, direction: .forward) == .notFound && ByteSearcher.find(SearchPattern(bytes: [1]), in: DataByteSource([]), startingAt: 0, direction: .forward) == .notFound && ByteSearcher.find(SearchPattern(bytes: []), in: small, startingAt: 0, direction: .forward) == .notFound, "a pattern longer than the file, an empty file and an empty pattern find nothing")
    check(ByteSearcher.find(SearchPattern(bytes: [1, 2, 3, 2, 3, 4]), in: small, startingAt: 0, direction: .forward) == .found(0..<6) && ByteSearcher.find(SearchPattern(bytes: [4]), in: small, startingAt: 0, direction: .backward) == .found(5..<6), "a match can be the whole file, or its last byte")
    check(ByteSearcher.find(SearchPattern(bytes: [0, 0], wildcard: [true, true]), in: small, startingAt: 4, direction: .forward, wraps: false) == .found(4..<6) && ByteSearcher.find(SearchPattern(bytes: [0, 0], wildcard: [true, true]), in: small, startingAt: 5, direction: .forward, wraps: false) == .notFound, "a pattern of only wildcards matches wherever it fits")
    // Letters.
    let letters = DataByteSource(Array("xAbCabcABC".utf8))
    let lower = SearchPattern(bytes: Array("abc".utf8), ignoresCase: true)
    var hits: [Int64] = []
    var next: Int64 = 0
    while case .found(let range) = ByteSearcher.find(lower, in: letters, startingAt: next, direction: .forward, wraps: false) { hits.append(range.lowerBound); next = range.lowerBound + 1 }
    check(hits == [1, 4, 7] && ByteSearcher.find(SearchPattern(bytes: Array("abc".utf8)), in: letters, startingAt: 0, direction: .forward, wraps: false) == .found(4..<7), "case is ignored for A to Z, and only then")
    check(ByteSearcher.find(SearchPattern(bytes: [0xC9], ignoresCase: true), in: DataByteSource([0xE9, 0xC9]), startingAt: 0, direction: .forward) == .found(1..<2) && SearchPattern.folded(0x40) == 0x40 && SearchPattern.folded(0x5B) == 0x5B && SearchPattern.folded(0x41) == 0x61 && SearchPattern.folded(0x5A) == 0x7A && SearchPattern.folded(0x61) == 0x61, "bytes beside the letters are never folded")
    // Stopping.
    var asked = 0
    let stopped = ByteSearcher.find(SearchPattern(bytes: [9]), in: DataByteSource([UInt8](repeating: 0, count: 100)), startingAt: 0, direction: .forward, chunk: 10, isCancelled: { asked += 1; return asked > 3 })
    check(stopped == .cancelled && asked == 4, "a search is stopped between chunks: \(stopped) after \(asked)")
    check(ByteSearcher.find(SearchPattern(bytes: [9]), in: small, startingAt: 0, direction: .forward, isCancelled: { true }) == .cancelled, "and before the first")
    var fractions: [Double] = []
    _ = ByteSearcher.find(SearchPattern(bytes: [9]), in: DataByteSource([UInt8](repeating: 0, count: 100)), startingAt: 0, direction: .forward, chunk: 10, progress: { fractions.append($0) })
    check(fractions.count == 10 && fractions == fractions.sorted() && fractions.last == 1 && fractions.allSatisfy { $0 > 0 && $0 <= 1 }, "progress goes up to one: \(fractions)")
    // A source that holds less than it said.
    final class ShortSource: ByteSource {
        var count: Int64 { 100 }
        func read(_ range: Range<Int64>) -> [UInt8] { Array(repeating: 7, count: Int(max(0, min(range.upperBound, 50) - min(range.lowerBound, 50)))) }
    }
    check(ByteSearcher.find(SearchPattern(bytes: [7, 7]), in: ShortSource(), startingAt: 60, direction: .forward, wraps: false, chunk: 16) == .notFound && ByteSearcher.find(SearchPattern(bytes: [7, 7]), in: ShortSource(), startingAt: 0, direction: .forward, chunk: 16) == .found(0..<2), "a file that shrank under the search is not read past what is there")
    // A file with edits over it is searched as the edits leave it.
    do {
        var buffer = ByteEditBuffer(source: DataByteSource(Array("hello world, hello".utf8)))
        _ = try? buffer.overwrite(at: 0, with: Array("J".utf8))
        try? buffer.insert(at: 6, bytes: Array("big ".utf8))
        let edited = EditedBytesSource(buffer)
        let found = ByteSearcher.find(SearchPattern(bytes: Array("big world".utf8)), in: edited, startingAt: 0, direction: .forward)
        let gone = ByteSearcher.find(SearchPattern(bytes: Array("hello world".utf8)), in: edited, startingAt: 0, direction: .forward)
        let last = ByteSearcher.find(SearchPattern(bytes: Array("hello".utf8)), in: edited, startingAt: 0, direction: .backward)
        check(edited.count == 22 && found == .found(6..<15) && gone == .notFound && last == .found(17..<22), "a search sees an overwrite and an insert: \(found) \(gone) \(last)")
    }
    // Many random searches against a plain loop.
    var random = BytesCheckRandom(seed: 0x5EA2C4)
    var sweepWrong: [String] = []
    for round in 0..<400 {
        let length = random.below(60)
        let data = (0..<length).map { _ in UInt8(random.below(4)) }
        let width = 1 + random.below(4)
        let bytes = (0..<width).map { _ in UInt8(random.below(4)) }
        let wild = (0..<width).map { _ in random.below(3) == 0 }
        let want = SearchPattern(bytes: bytes, wildcard: wild)
        let starts = (0..<max(0, length - width + 1)).filter { start in (0..<width).allSatisfy { wild[$0] || data[start + $0] == bytes[$0] } }.map { Int64($0) }
        let start = Int64(random.below(length + 6)) - 3
        let forward = random.below(2) == 0
        let wraps = random.below(2) == 0
        var expected: SearchOutcome = .notFound
        if forward {
            if let first = starts.first(where: { $0 >= start }) { expected = .found(first..<(first + Int64(width))) }
            else if wraps, let first = starts.first(where: { $0 < start }) { expected = .found(first..<(first + Int64(width))) }
        } else {
            if let last = starts.last(where: { $0 <= start }) { expected = .found(last..<(last + Int64(width))) }
            else if wraps, let last = starts.last(where: { $0 > start }) { expected = .found(last..<(last + Int64(width))) }
        }
        let got = ByteSearcher.find(want, in: DataByteSource(data), startingAt: start, direction: forward ? .forward : .backward, wraps: wraps, chunk: 1 + random.below(9))
        if got != expected { sweepWrong.append("round \(round): \(forward ? "forward" : "back") from \(start) wraps \(wraps) in \(length) bytes: \(got) not \(expected)") }
    }
    check(sweepWrong.isEmpty, "400 random searches agree with a plain loop: \(sweepWrong.prefix(2))")
}
checkByteSearch()

// MARK: Typing and saving

// What typing does to the bytes (where a digit lands, what the second digit changes, where the cursor goes, what Delete is for)
// is checked on scenarios whose answers are written out, and against a plain array on random keystrokes. Saving is checked on
// real files in a folder made for it: what is written, what is left behind, and what is refused.

func checkTypingAndSaving() {
    func buffer(_ bytes: [UInt8]) -> ByteEditBuffer { ByteEditBuffer(source: DataByteSource(bytes)) }
    func content(_ buffer: ByteEditBuffer) -> [UInt8] { buffer.read(0..<buffer.length) }
    func digits(_ text: String) -> [UInt8] { text.compactMap { UInt8(String($0), radix: 16) } }

    // Overwriting: two digits make a byte, and the cursor moves on.
    do {
        var b = buffer([0x00, 0x11, 0x22, 0x33])
        var typing = ByteTyping()
        var cursor: ByteSelection? = ByteSelection(at: 1)
        for digit in digits("ABCD") { cursor = try? typing.hexDigit(digit, in: &b, at: cursor) ?? nil }
        check(content(b) == [0x00, 0xAB, 0xCD, 0x33] && cursor == ByteSelection(at: 3), "two digits make a byte, the next two the next: \(content(b)) \(String(describing: cursor))")
        check(b.undo() && content(b) == [0x00, 0x11, 0x22, 0x33] && !b.canUndo, "and the whole run is one step of undo")
        // The first digit shows at once, over the low half that is still there.
        var c = buffer([0x00, 0x11])
        var t2 = ByteTyping()
        var wide = buffer([0x00, 0x00])
        var t0 = ByteTyping()
        _ = try? t0.hexDigit(0x1A, in: &wide, at: ByteSelection(at: 0))
        _ = try? t0.hexDigit(0x1B, in: &wide, at: ByteSelection(at: 0))
        check(content(wide) == [0xAB, 0x00], "only the low four bits of a digit are used")
        let after = try? t2.hexDigit(0xF, in: &c, at: ByteSelection(at: 1))
        check(content(c) == [0x00, 0xF1] && after == ByteSelection(at: 1) && t2.pendingDigit == 1, "the first digit sets the high half and the cursor waits")
        _ = try? t2.hexDigit(0x2, in: &c, at: ByteSelection(at: 1))
        check(content(c) == [0x00, 0xF2] && t2.pendingDigit == nil, "the second sets the low half, and at the last byte the cursor stays")
        // A cursor that moved away drops the half-typed byte.
        var d = buffer([0x00, 0x11, 0x22])
        var t3 = ByteTyping()
        _ = try? t3.hexDigit(0xA, in: &d, at: ByteSelection(at: 0))
        t3.forget()
        _ = try? t3.hexDigit(0xB, in: &d, at: ByteSelection(at: 1))
        check(content(d) == [0xA0, 0xB1, 0x22] && t3.pendingDigit == 1, "a digit typed elsewhere starts a byte there")
        // A selection of many bytes: typing starts at its first.
        var e = buffer([1, 2, 3, 4, 5])
        var t4 = ByteTyping()
        let landed = try? t4.hexDigit(0x9, in: &e, at: ByteSelection(anchor: 3, head: 1))
        check(content(e) == [1, 0x92, 3, 4, 5] && landed == ByteSelection(at: 1), "typing over a selection starts at its first byte")
    }
    // Inserting: new bytes are put in before the cursor, and the rest moves along.
    do {
        var b = buffer([0x00, 0x11])
        var typing = ByteTyping()
        typing.mode = .insert
        var cursor: ByteSelection? = ByteSelection(at: 1)
        for digit in digits("ABCD") { cursor = try? typing.hexDigit(digit, in: &b, at: cursor) ?? nil }
        check(content(b) == [0x00, 0xAB, 0xCD, 0x11] && cursor == ByteSelection(at: 3), "in insert mode typed bytes go in before the byte under the cursor: \(content(b))")
        check(b.undo() && content(b) == [0x00, 0x11] && !b.canUndo, "and are one step of undo")
        // Adding at the end is asked for.
        var c = buffer([0x00, 0x11])
        var t2 = ByteTyping()
        t2.mode = .insert
        var at = t2.beginAppending(to: c)
        check(at == ByteSelection(at: 1), "appending puts the cursor on the last byte")
        for digit in digits("ABCD") { at = try? t2.hexDigit(digit, in: &c, at: at) ?? nil }
        check(content(c) == [0x00, 0x11, 0xAB, 0xCD] && at == ByteSelection(at: 3), "and what is typed goes after it, byte after byte: \(content(c))")
        // The first digit alone has put a byte in.
        var d = buffer([0x00])
        var t3 = ByteTyping()
        t3.mode = .insert
        _ = try? t3.hexDigit(0x7, in: &d, at: ByteSelection(at: 0))
        check(content(d) == [0x70, 0x00] && t3.pendingDigit == 0, "the first digit of an inserted byte shows at once")
    }
    // Text.
    do {
        var b = buffer(Array("abcdef".utf8))
        var typing = ByteTyping()
        let after = try? typing.text("XY", in: &b, at: ByteSelection(at: 1))
        check(String(decoding: content(b), as: UTF8.self) == "aXYdef" && after == ByteSelection(at: 3), "text overwrites what is under the cursor, and the cursor goes past it")
        let atEnd = try? typing.text("ZZZZZZ", in: &b, at: ByteSelection(at: 4))
        check(String(decoding: content(b), as: UTF8.self) == "aXYdZZ" && b.length == 6 && atEnd == ByteSelection(at: 5), "and stops at the end of the file, with the cursor on the last byte")
        let del = try? typing.text("\u{7F}", in: &b, at: ByteSelection(at: 0))
        check(del == ByteSelection(at: 0) && String(decoding: content(b), as: UTF8.self) == "aXYdZZ", "DEL is a control character too")
        typing.mode = .insert
        let inserted = try? typing.text("--", in: &b, at: ByteSelection(at: 2))
        check(String(decoding: content(b), as: UTF8.self) == "aX--YdZZ" && inserted == ByteSelection(at: 4), "in insert mode it is put in")
        _ = try? typing.text("é", in: &b, at: ByteSelection(at: 0))
        check(content(b).prefix(3) == [0xC3, 0xA9, 0x61], "a character beyond ASCII is its UTF-8 bytes")
        let same = try? typing.text("\r\u{1B}\t", in: &b, at: ByteSelection(at: 0))
        check(same == ByteSelection(at: 0) && content(b).count == 10, "control characters are left out")
    }
    // Deleting.
    do {
        var b = buffer([1, 2, 3, 4, 5, 6])
        var typing = ByteTyping()
        var failure: ByteTyping.Failure?
        do { _ = try typing.deleteBackward(in: &b, at: ByteSelection(at: 2)) } catch { failure = error as? ByteTyping.Failure }
        check(failure == .needsInsertMode && content(b) == [1, 2, 3, 4, 5, 6], "Delete does nothing in overwrite mode, and says why")
        typing.mode = .insert
        let back = try? typing.deleteBackward(in: &b, at: ByteSelection(at: 2))
        check(content(b) == [1, 3, 4, 5, 6] && back == ByteSelection(at: 1), "Backspace takes out the byte before the cursor")
        let forward = try? typing.deleteForward(in: &b, at: ByteSelection(at: 1))
        check(content(b) == [1, 4, 5, 6] && forward == ByteSelection(at: 1), "Delete takes out the byte under it")
        let range = try? typing.deleteForward(in: &b, at: ByteSelection(anchor: 3, head: 1))
        check(content(b) == [1] && range == ByteSelection(at: 0), "either takes out a selection, and the cursor stays inside the file")
        let atStart = try? typing.deleteBackward(in: &b, at: ByteSelection(at: 0))
        check(content(b) == [1] && atStart == ByteSelection(at: 0), "Backspace at the start takes out nothing")
        let emptied = try? typing.deleteForward(in: &b, at: ByteSelection(at: 0))
        check(b.length == 0 && emptied == nil, "taking out everything leaves no cursor")
        var none: ByteTyping.Failure?
        do { _ = try typing.deleteForward(in: &b, at: nil) } catch { none = error as? ByteTyping.Failure }
        check(none == .nothing, "and nothing is left to take out")
        // Typing into an empty buffer in insert mode.
        let first = try? typing.hexDigit(0xA, in: &b, at: nil)
        check(content(b) == [0xA0] && first == .some(ByteSelection(at: 0)), "insert mode can start from nothing")
        var overwrite = ByteTyping()
        var empty = buffer([])
        var nothing: ByteTyping.Failure?
        do { _ = try overwrite.hexDigit(1, in: &empty, at: nil) } catch { nothing = error as? ByteTyping.Failure }
        check(nothing == .nothing, "and overwrite mode cannot")
    }
    // Filling.
    do {
        var b = buffer([1, 2, 3, 4, 5])
        var typing = ByteTyping()
        try? typing.fill(0xFF, in: &b, at: ByteSelection(anchor: 3, head: 1))
        check(content(b) == [1, 0xFF, 0xFF, 0xFF, 5] && b.undo() && content(b) == [1, 2, 3, 4, 5], "a selection is filled in one step")
    }
    // Refusals.
    do {
        var b = buffer([1, 2, 3, 4])
        b.pieceLimit = 3
        var typing = ByteTyping()
        typing.mode = .insert
        var refused: ByteTyping.Failure?
        var cursor: ByteSelection? = ByteSelection(at: 0)
        for round in 0..<6 {
            do { cursor = try typing.text("x", in: &b, at: ByteSelection(at: Int64((round * 2) % max(1, Int(b.length))))) ?? cursor } catch { refused = error as? ByteTyping.Failure; break }
        }
        check(refused == .edit(.tooManyPieces) || refused == nil, "a buffer that refuses an edit says so, and is left as it was")
        _ = cursor
    }

    // Many random keystrokes against a plain array that follows the same rules.
    var random = BytesCheckRandom(seed: 0xED17)
    var sweepWrong: [String] = []
    for round in 0..<300 {
        let start = (0..<(1 + random.below(12))).map { _ in UInt8(random.below(256)) }
        var b = buffer(start)
        var model = start
        var typing = ByteTyping()
        var cursor: ByteSelection? = ByteSelection(at: Int64(random.below(start.count)))
        var pending: Int?
        var appending: Int?
        var insert = false
        var history: [[UInt8]] = [start]
        for step in 0..<40 {
            let at = Int(cursor?.lowerBound ?? 0)
            switch random.below(8) {
            case 0, 1, 2:
                // a hex digit
                let digit = UInt8(random.below(16))
                guard let landed = try? typing.hexDigit(digit, in: &b, at: cursor) else { continue }
                if let p = pending, p == at, at < model.count {
                    model[at] = (model[at] & 0xF0) | digit
                    pending = nil
                    if at + 1 < model.count { appending = nil; cursor = ByteSelection(at: Int64(at + 1)) } else { appending = insert ? at : nil; cursor = ByteSelection(at: Int64(at)) }
                } else if insert {
                    let place = (appending == at && at == model.count - 1) ? model.count : at
                    model.insert(digit << 4, at: place)
                    pending = place
                    appending = nil
                    cursor = ByteSelection(at: Int64(place))
                } else {
                    model[at] = (digit << 4) | (model[at] & 0x0F)
                    pending = at
                    appending = nil
                    cursor = ByteSelection(at: Int64(at))
                }
                if landed != cursor { sweepWrong.append("round \(round) step \(step): cursor \(String(describing: landed)) not \(String(describing: cursor))") }
                history.append(model)
            case 3:
                // text
                let letters = String((0..<(1 + random.below(3))).map { _ in Character(UnicodeScalar(UInt8(0x61 + random.below(26)))) })
                guard (try? typing.text(letters, in: &b, at: cursor)) != nil else { continue }
                let bytes = Array(letters.utf8)
                pending = nil
                if insert {
                    let place = (appending == at && at == model.count - 1) ? model.count : at
                    model.insert(contentsOf: bytes, at: place)
                    let next = place + bytes.count
                    if next >= model.count { appending = model.count - 1; cursor = ByteSelection(at: Int64(model.count - 1)) } else { appending = nil; cursor = ByteSelection(at: Int64(next)) }
                } else {
                    let written = min(bytes.count, model.count - at)
                    model.replaceSubrange(at..<(at + written), with: bytes[0..<written])
                    appending = nil
                    cursor = ByteSelection(at: Int64(min(at + written, model.count - 1)))
                }
                history.append(model)
            case 4:
                // move the cursor
                typing.forget()
                pending = nil
                appending = nil
                cursor = ByteSelection(at: Int64(random.below(max(1, model.count))))
            case 5:
                typing.mode = typing.mode == .insert ? .overwrite : .insert
                insert = typing.mode == .insert
            case 6:
                guard insert, !model.isEmpty, let current = cursor else { continue }
                let forward = random.below(2) == 0
                let result = forward ? try? typing.deleteForward(in: &b, at: current) : try? typing.deleteBackward(in: &b, at: current)
                pending = nil
                appending = nil
                let lower = Int(current.lowerBound)
                let upper = Int(current.upperBound)
                var removed: Range<Int>?
                if current.count > 1 { removed = lower..<(upper + 1) }
                else if forward { removed = lower..<(lower + 1) }
                else if lower > 0 { removed = (lower - 1)..<lower }
                if let removed {
                    model.removeSubrange(removed)
                    let place = forward || current.count > 1 ? lower : lower - 1
                    cursor = model.isEmpty ? nil : ByteSelection(at: Int64(min(max(place, 0), model.count - 1)))
                } else {
                    cursor = current
                }
                if result != cursor { sweepWrong.append("round \(round) step \(step): delete cursor \(String(describing: result)) not \(String(describing: cursor))") }
                history.append(model)
            default:
                // undo, then redo
                let before = content(b)
                if b.undo() {
                    pending = nil
                    appending = nil
                    typing.forget()
                    if b.redo() == false || content(b) != before { sweepWrong.append("round \(round) step \(step): redo did not put it back") }
                    cursor = ByteSelection(at: Int64(min(Int(cursor?.lowerBound ?? 0), max(0, Int(b.length) - 1))))
                }
            }
            if content(b) != model {
                sweepWrong.append("round \(round) step \(step): \(content(b).prefix(8)) is not \(model.prefix(8))")
                break
            }
            if b.length == 0 { break }
        }
        // Everything done can be undone, back to the start.
        while b.undo() {}
        if content(b) != start { sweepWrong.append("round \(round): undoing everything gave \(content(b).prefix(8)) not \(start.prefix(8))") }
        if sweepWrong.count > 3 { break }
    }
    check(sweepWrong.isEmpty, "300 rounds of random typing, deleting, mode changes and undo agree with a plain array: \(sweepWrong.prefix(2))")

    // Which bytes changed.
    do {
        var b = buffer([1, 2, 3, 4, 5, 6, 7, 8])
        check(b.changedRanges() == [], "an unchanged buffer has no changed bytes")
        _ = try? b.overwrite(at: 1, with: [9, 9])
        _ = try? b.overwrite(at: 6, with: [0])
        try? b.fill(3..<4, with: 0xAA)
        check(b.changedRanges() == [1..<4, 6..<7], "overwritten and filled runs are the changed ones, joined where they touch: \(String(describing: b.changedRanges()))")
        try? b.insert(at: 2, bytes: [1])
        check(b.changedRanges() == nil, "an insert means no list")
        var longer = buffer([1, 2, 3])
        try? longer.insert(at: 3, bytes: [4])
        check(longer.changedRanges() == nil, "and so does one at the end")
        var shorter = buffer([1, 2, 3])
        try? shorter.delete(2..<3)
        check(shorter.changedRanges() == nil, "or a delete")
        try? b.delete(2..<3)
        check(b.changedRanges() != nil, "an insert taken out again does not")
        var c = buffer([1, 2, 3, 4, 5, 6])
        try? c.insert(at: 1, bytes: [7])
        try? c.delete(4..<5)
        check(c.changedRanges() == nil, "an insert and a delete that leave the length alone still move what is between them")
        var d = buffer([1, 2, 3, 4])
        try? d.insert(at: 4, bytes: [9])
        try? d.delete(0..<1)
        check(d.changedRanges() == nil, "or at the ends")
    }

    // Saving, on real files.
    let folder = FileManager.default.temporaryDirectory.appendingPathComponent("iterminal-save-\(UUID().uuidString.prefix(8))")
    try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: folder) }
    func make(_ name: String, _ bytes: [UInt8], mode: Int = 0o644) -> URL {
        let url = folder.appendingPathComponent(name)
        FileManager.default.createFile(atPath: url.path, contents: Data(bytes), attributes: [.posixPermissions: mode])
        return url
    }
    func open(_ url: URL) -> FileByteSource? { if case .success(let source) = FileByteSource.opening(path: url.path) { return source } else { return nil } }
    func read(_ url: URL) -> [UInt8] { [UInt8](FileManager.default.contents(atPath: url.path) ?? Data()) }
    func names() -> [String] { ((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []).sorted() }

    var saveWrong: [String] = []
    do {
        // Only overwrites: a copy with the changed bytes written into it.
        let original = (0..<5000).map { UInt8($0 % 251) }
        let url = make("patch.bin", original)
        guard let source = open(url) else { saveWrong.append("could not open patch.bin"); throw ByteEditError.tooManyPieces }
        var b = ByteEditBuffer(source: source)
        try b.overwrite(at: 10, with: [0xDE, 0xAD])
        try b.fill(4000..<4100, with: 0x55)
        let method = try ByteFileSaver.save(b, over: source, keepsBackup: false, chunk: 64)
        var expected = original
        expected.replaceSubrange(10..<12, with: [0xDE, 0xAD])
        for i in 4000..<4100 { expected[i] = 0x55 }
        if read(url) != expected { saveWrong.append("patched file differs") }
        if method != .patchedCopy(changedBytes: 102) { saveWrong.append("method \(method)") }
        if names() != ["patch.bin"] { saveWrong.append("left behind: \(names())") }
    } catch { saveWrong.append("patch: \(error)") }
    do {
        // An insert and a delete: the whole content written out, with the original's permissions.
        let original = (0..<3000).map { UInt8(($0 * 7) % 256) }
        let url = make("rewrite.bin", original, mode: 0o640)
        guard let source = open(url) else { saveWrong.append("could not open rewrite.bin"); throw ByteEditError.tooManyPieces }
        var b = ByteEditBuffer(source: source)
        try b.insert(at: 100, bytes: [1, 2, 3, 4, 5])
        try b.delete(2000..<2010)
        let method = try ByteFileSaver.save(b, over: source, keepsBackup: false, chunk: 100)
        var expected = original
        expected.insert(contentsOf: [1, 2, 3, 4, 5], at: 100)
        expected.removeSubrange(2000..<2010)
        if read(url) != expected { saveWrong.append("rewritten file differs") }
        if method != .rewritten { saveWrong.append("method \(method)") }
        var info = stat()
        stat(url.path, &info)
        if info.st_mode & 0o7777 != 0o640 { saveWrong.append("permissions \(String(info.st_mode & 0o7777, radix: 8))") }
        if !names().allSatisfy({ !$0.hasSuffix(".tmp") }) { saveWrong.append("a temporary file was left: \(names())") }
    } catch { saveWrong.append("rewrite: \(error)") }
    do {
        // A backup of what was there.
        let url = make("backup.bin", [1, 2, 3, 4])
        guard let source = open(url) else { saveWrong.append("could not open backup.bin"); throw ByteEditError.tooManyPieces }
        var b = ByteEditBuffer(source: source)
        try b.overwrite(at: 0, with: [9])
        try ByteFileSaver.save(b, over: source, keepsBackup: true)
        if read(url) != [9, 2, 3, 4] { saveWrong.append("backup: saved file is \(read(url))") }
        if read(folder.appendingPathComponent("backup.bin.bak")) != [1, 2, 3, 4] { saveWrong.append("backup: .bak is \(read(folder.appendingPathComponent("backup.bin.bak")))") }
    } catch { saveWrong.append("backup: \(error)") }
    do {
        // A file changed by someone else is not written over.
        let url = make("changed.bin", [1, 2, 3, 4])
        guard let source = open(url) else { saveWrong.append("could not open changed.bin"); throw ByteEditError.tooManyPieces }
        var b = ByteEditBuffer(source: source)
        try b.overwrite(at: 0, with: [9])
        let handle = FileHandle(forWritingAtPath: url.path)
        try handle?.seekToEnd()
        try handle?.write(contentsOf: Data([0xEE]))
        try handle?.close()
        var failure: ByteFileSaver.Failure?
        do { try ByteFileSaver.save(b, over: source, keepsBackup: false) } catch { failure = error as? ByteFileSaver.Failure }
        if failure != .changedOnDisk(.grew) { saveWrong.append("changed: \(String(describing: failure))") }
        if read(url) != [1, 2, 3, 4, 0xEE] { saveWrong.append("changed: the file was touched: \(read(url))") }
        try FileManager.default.removeItem(at: url)
        var gone: ByteFileSaver.Failure?
        do { try ByteFileSaver.save(b, over: source, keepsBackup: false) } catch { gone = error as? ByteFileSaver.Failure }
        if gone != .changedOnDisk(.missing) { saveWrong.append("missing: \(String(describing: gone))") }
        if FileManager.default.fileExists(atPath: url.path) { saveWrong.append("missing: a file appeared") }
    } catch { saveWrong.append("changed: \(error)") }
    do {
        // Room.
        let url = make("room.bin", [1, 2, 3, 4])
        guard let source = open(url) else { saveWrong.append("could not open room.bin"); throw ByteEditError.tooManyPieces }
        var b = ByteEditBuffer(source: source)
        try b.overwrite(at: 0, with: [9])
        var failure: ByteFileSaver.Failure?
        do { try ByteFileSaver.save(b, over: source, keepsBackup: false, freeSpace: { _ in 100 }) } catch { failure = error as? ByteFileSaver.Failure }
        // All four bytes are needed where a copy is a copy; one, where the volume clones and only the changed byte is written.
        if failure != .notEnoughSpace(needed: 4, available: 100) && failure != .notEnoughSpace(needed: 1, available: 100) { saveWrong.append("room: \(String(describing: failure))") }
        if read(url) != [1, 2, 3, 4] { saveWrong.append("room: the file was touched") }
        // Nothing left.
        try b.delete(0..<4)
        var empty: ByteFileSaver.Failure?
        do { try ByteFileSaver.save(b, over: source, keepsBackup: false) } catch { empty = error as? ByteFileSaver.Failure }
        if empty != .wouldBeEmpty { saveWrong.append("empty: \(String(describing: empty))") }
        if !names().allSatisfy({ !$0.hasSuffix(".tmp") }) { saveWrong.append("a temporary file was left after a refusal: \(names())") }
    } catch { saveWrong.append("room: \(error)") }
    do {
        // Through a link: the file it names is saved, and the link stays a link.
        let target = make("target.bin", [1, 2, 3, 4])
        let link = folder.appendingPathComponent("link.bin")
        try FileManager.default.createSymbolicLink(at: link, withDestinationURL: target)
        guard let source = open(link) else { saveWrong.append("could not open link.bin"); throw ByteEditError.tooManyPieces }
        var b = ByteEditBuffer(source: source)
        try b.insert(at: 0, bytes: [0])
        try ByteFileSaver.save(b, over: source, keepsBackup: false)
        let kind = try FileManager.default.attributesOfItem(atPath: link.path)[.type] as? FileAttributeType
        if read(target) != [0, 1, 2, 3, 4] || kind != .typeSymbolicLink { saveWrong.append("link: target \(read(target)), kind \(String(describing: kind))") }
    } catch { saveWrong.append("link: \(error)") }
    do {
        // A file with another name (a hard link): replacing it would leave the other name with the old bytes, so it is refused.
        let url = make("linked.bin", [1, 2, 3, 4])
        let other = folder.appendingPathComponent("other-name.bin")
        try FileManager.default.linkItem(at: url, to: other)
        if ByteFileSaver.nameCount(ofFileAt: url.path) != 2 { saveWrong.append("hard link: \(String(describing: ByteFileSaver.nameCount(ofFileAt: url.path))) names") }
        guard let source = open(url) else { saveWrong.append("could not open linked.bin"); throw ByteEditError.tooManyPieces }
        var b = ByteEditBuffer(source: source)
        try b.overwrite(at: 0, with: [9])
        var failure: ByteFileSaver.Failure?
        do { try ByteFileSaver.save(b, over: source, keepsBackup: true) } catch { failure = error as? ByteFileSaver.Failure }
        if failure != .hasOtherNames(2) { saveWrong.append("hard link: \(String(describing: failure))") }
        if read(url) != [1, 2, 3, 4] || read(other) != [1, 2, 3, 4] { saveWrong.append("hard link: a file was touched") }
        if names().contains(where: { $0.hasSuffix(".tmp") || $0 == "linked.bin.bak" }) { saveWrong.append("hard link: something was left behind: \(names())") }
        try FileManager.default.removeItem(at: other)
        try ByteFileSaver.save(b, over: source, keepsBackup: false)
        if read(url) != [9, 2, 3, 4] { saveWrong.append("hard link: with the other name gone it should save: \(read(url))") }
    } catch { saveWrong.append("hard link: \(error)") }
    do {
        // A save that is done can be followed by opening the file again and saving again.
        let url = make("twice.bin", [1, 2, 3])
        var source = open(url)
        var b = ByteEditBuffer(source: source!)
        try b.overwrite(at: 0, with: [7])
        try ByteFileSaver.save(b, over: source!, keepsBackup: false)
        source = open(url)
        b = ByteEditBuffer(source: source!)
        try b.overwrite(at: 2, with: [8])
        try ByteFileSaver.save(b, over: source!, keepsBackup: false)
        if read(url) != [7, 2, 8] { saveWrong.append("twice: \(read(url))") }
    } catch { saveWrong.append("twice: \(error)") }
    check(saveWrong.isEmpty, "saving writes what the buffer holds, keeps the permissions and the link, makes a backup if asked, and refuses over a changed file, a full disk or an empty result: \(saveWrong.prefix(3))")
    check(ByteFileSaver.message(.changedOnDisk(.grew), name: "a").contains("changed") && ByteFileSaver.message(.changedOnDisk(.replaced), name: "a").contains("replaced") && ByteFileSaver.message(.changedOnDisk(.missing), name: "a").contains("gone")
          && ByteFileSaver.message(.notEnoughSpace(needed: 5, available: 2), name: "a").contains("5 bytes") && ByteFileSaver.message(.wouldBeEmpty, name: "a").contains("no bytes")
          && ByteFileSaver.message(.cannotWrite("denied"), name: "a").contains("denied") && ByteFileSaver.message(.lengthMismatch(written: 1, expected: 2), name: "a").contains("1 byte") && ByteFileSaver.message(.unreadable(offset: 9), name: "a").contains("9")
          && ByteFileSaver.message(.hasOtherNames(2), name: "a").contains("1 other name ") && ByteFileSaver.message(.hasOtherNames(3), name: "a").contains("2 other names"), "every way a save fails has words")
    check(ByteFileSaver.nameCount(ofFileAt: "/no/such/file") == nil, "a file that is not there has no count of names")
    do {
        var b = buffer((0..<100).map { UInt8($0) })
        _ = try? b.overwrite(at: 10, with: [0xFF, 0xFE, 0xFD])
        try? b.fill(50..<60, with: 0)
        check(ByteFileSaver.spaceNeeded(for: b, clones: true) == 13 && ByteFileSaver.spaceNeeded(for: b, clones: false) == 100, "where a copy shares the original's data, a save of overwrites needs room for the changed bytes alone")
        try? b.insert(at: 0, bytes: [1])
        check(ByteFileSaver.spaceNeeded(for: b, clones: true) == 101 && ByteFileSaver.spaceNeeded(for: b, clones: false) == 101, "and an insert means the whole file is written, wherever it is")
        check(ByteFileSaver.clonesFiles(inFolder: URL(fileURLWithPath: "/no/such/folder")) == false, "a folder that is not there clones nothing")
    }
    check(ByteFileSaver.freeSpace(inFolder: folder.path).map { $0 > 0 } == true && ByteFileSaver.freeSpace(inFolder: "/no/such/folder") == nil, "free space is read from the folder")
}
checkTypingAndSaving()

// MARK: The structure tree as lines

func checkTheStructureTreeAsLines() {
    let png = FormatRegistry.analyze(DataByteSource(structureBytes("89504e470d0a1a0a0000000d4948445200000002000000010806000000f4227f8a0000000d74455874436f6d6d656e740068656c6c6fe6ffae240000000970485973000016250000162501495224f00000001149444154789c63f8cfc0f09f81e17f03000f7a037e0bcb2eb10000000049454e44ae426082")))
    let roots = png.outcome.roots

    var rows = StructureOutline.rows(roots: roots, expanded: [], limits: [:])
    check(rows.map(\.id) == roots.map(\.id) && rows.allSatisfy { $0.depth == 0 && !$0.isExpanded }, "with nothing open there is a line for each field at the top")
    check(roots.map(\.id) == FormatRegistry.analyze(DataByteSource(structureBytes("89504e470d0a1a0a0000000d4948445200000002000000010806000000f4227f8a0000000d74455874436f6d6d656e740068656c6c6fe6ffae240000000970485973000016250000162501495224f00000001149444154789c63f8cfc0f09f81e17f03000f7a037e0bcb2eb10000000049454e44ae426082"))).outcome.roots.map(\.id), "and a second parse of the same file gives the same ids, so what was open stays open")

    rows = StructureOutline.rows(roots: roots, expanded: ["png/chunk1-IHDR"], limits: [:])
    check(rows.count == roots.count + 4 && rows[2].depth == 1 && rows[1].isExpanded, "opening a chunk adds its four fields under it")
    rows = StructureOutline.rows(roots: roots, expanded: ["png/chunk1-IHDR", "png/chunk1-IHDR/data"], limits: [:])
    check(rows.count == roots.count + 4 + 7 && rows.contains { $0.id == "png/chunk1-IHDR/data/width" && $0.depth == 2 }, "and opening its data adds the seven fields in it")
    rows = StructureOutline.rows(roots: roots, expanded: ["png/chunk1-IHDR/data/width", "png/signature"], limits: [:])
    check(rows.count == roots.count && rows.allSatisfy { !$0.isExpanded }, "a field with nothing in it is never shown open")
    rows = StructureOutline.rows(roots: roots, expanded: ["png/chunk1-IHDR/data"], limits: [:])
    check(rows.count == roots.count, "and one inside a field that is closed is not shown")

    // A level of twelve hundred fields lists a page of them, and a line for the rest.
    var wide: [FieldNode] = []
    for i in 0..<1200 { wide.append(FieldNode(id: "w\(i)", name: "W\(i)", offset: Int64(i) * 10, length: 10, kind: .bytes)) }
    rows = StructureOutline.rows(roots: wide, expanded: [], limits: [:])
    var more: String?
    if case .more(let parent, let remaining) = rows.last?.content { more = "\(parent):\(remaining)" }
    check(rows.count == 501 && more == ":700" && rows.last?.id == "more:", "twelve hundred fields list five hundred and a line for the other 700: \(rows.count) \(more ?? "")")
    var limits = StructureOutline.showingMore(under: "", limits: [:])
    rows = StructureOutline.rows(roots: wide, expanded: [], limits: limits)
    check(rows.count == 1001, "asking for more adds a page")
    limits = StructureOutline.showingMore(under: "", limits: limits)
    rows = StructureOutline.rows(roots: wide, expanded: [], limits: limits)
    check(rows.count == 1200 && rows.allSatisfy { if case .node = $0.content { return true } else { return false } }, "and again lists them all, with no line for more")

    // A byte far down is brought into the list.
    let far = StructureOutline.reveal(offset: 9_005, in: wide, limits: [:])
    check(far.focus?.id == "w900" && far.open.isEmpty && (far.limits[""] ?? 0) >= 950, "a byte in the 901st field raises the limit to show it: \(far.limits)")
    rows = StructureOutline.rows(roots: wide, expanded: Set(far.open), limits: far.limits)
    check(rows.contains { $0.id == "w900" }, "and then it is in the list")
    let near = StructureOutline.reveal(offset: 15, in: wide, limits: [:])
    check(near.focus?.id == "w1" && near.limits.isEmpty, "a byte near the top changes no limit")
    let nowhere = StructureOutline.reveal(offset: 99_999, in: wide, limits: [:])
    check(nowhere.focus == nil && nowhere.open.isEmpty, "a byte in no field has no field")

    // Into the PNG: the fields to open to see the one that holds a byte.
    let height = StructureOutline.reveal(offset: 20, in: roots, limits: [:])
    check(height.focus?.name == "Height" && height.open == ["png/chunk1-IHDR", "png/chunk1-IHDR/data"], "the Height field is shown by opening IHDR and its data: \(height.open)")
    rows = StructureOutline.rows(roots: roots, expanded: Set(height.open), limits: height.limits)
    check(rows.contains { $0.id == height.focus?.id } && rows.first(where: { $0.id == height.focus?.id })?.depth == 2, "and it is then a line, two levels in")
    let magic = StructureOutline.reveal(offset: 2, in: roots, limits: [:])
    check(magic.focus?.name == "Signature" && magic.open.isEmpty, "a byte of the signature opens nothing")
    let chunk = StructureOutline.reveal(offset: 112, in: roots, limits: [:])
    check(chunk.focus?.name == "Type" && chunk.open == ["png/chunk5-IEND"], "and one of IEND's type opens IEND")

    // Packets: the field a byte is in, down through the packet, from a capture of many.
    let capture = FormatRegistry.analyze(DataByteSource(structureBytes("")))
    let timestamp = StructureOutline.reveal(offset: 100, in: capture.outcome.roots, limits: [:])
    check(timestamp.focus?.name == "Timestamps" && timestamp.open == ["pcap/pkt1", "pcap/pkt1/packet", "pcap/pkt1/packet/tcp", "pcap/pkt1/packet/tcp/options"], "a byte of a TCP option opens the packet, its data, TCP and its options: \(timestamp.open)")

    // Many open levels never make more than the most lines.
    var deep = FieldNode(id: "leaf", name: "Leaf", offset: 0, length: 1, kind: .bytes)
    var open: Set<String> = []
    for level in 0..<30 {
        var siblings: [FieldNode] = []
        for i in 0..<30 { siblings.append(FieldNode(id: "L\(level)-\(i)", name: "N", offset: 0, length: 1, kind: .bytes)) }
        deep = FieldNode(id: "L\(level)", name: "Level", offset: 0, length: 1, kind: .container, children: .list(siblings + [deep]))
        open.insert("L\(level)")
    }
    check(StructureOutline.rows(roots: [deep], expanded: open, limits: [:]).count <= StructureOutline.maxRows, "however much is open, the lines stop at a limit")

    let flag = ParseCancellation()
    check(!flag.isCancelled, "a parse nobody has stopped is not cancelled")
    flag.cancel()
    check(flag.isCancelled, "and one that was is")
}
checkTheStructureTreeAsLines()

// MARK: The Bytes panel's map and entropy graph

// The map and the graph are arithmetic on a file's bytes, so they are checked against numbers worked
// out a second way: Python's integers, `bisect`, `Counter` and `math.log2`, written from the rules and
// not from the Swift. Where there is no second way to work a thing out (that a curve is a Hilbert curve),
// it is checked by what is true of every such curve: it visits every cell once and never jumps.

struct MapLayoutFixture {
    let length: Int64
    let order: Int
    let cells: Int
    let windows: Int
    /// Pairs: a cell number, and where that cell starts.
    let starts: [Int64]
    /// Pairs: a byte offset, and the cell that holds it.
    let containing: [Int64]
}

/// A file that is never held in memory: the byte at an offset is a function of the offset. It
/// remembers what it was asked for.
final class MapFormulaSource: ByteSource {
    let count: Int64
    private(set) var requests: [Range<Int64>] = []
    private(set) var bytesRead: Int64 = 0

    init(count: Int64) { self.count = count }

    static func byte(at offset: Int64) -> UInt8 {
        UInt8(truncatingIfNeeded: (UInt64(truncatingIfNeeded: offset) &* 2654435761) >> 7)
    }

    func read(_ range: Range<Int64>) -> [UInt8] {
        let limited = clamped(range)
        requests.append(limited)
        bytesRead += limited.upperBound - limited.lowerBound
        var bytes: [UInt8] = []
        bytes.reserveCapacity(Int(limited.upperBound - limited.lowerBound))
        var offset = limited.lowerBound
        while offset < limited.upperBound {
            bytes.append(MapFormulaSource.byte(at: offset))
            offset += 1
        }
        return bytes
    }
}

/// A source that counts what it is asked for, and from some offset on has nothing to give, as a
/// file does that shrinks while it is being read.
final class MapProbeSource: ByteSource {
    let count: Int64
    var readable: Int64
    private(set) var reads = 0
    private let inner: ByteSource

    init(_ inner: ByteSource, readable: Int64? = nil) {
        self.inner = inner
        count = inner.count
        self.readable = readable ?? inner.count
    }

    func read(_ range: Range<Int64>) -> [UInt8] {
        reads += 1
        let limited = clamped(range)
        let end = min(limited.upperBound, readable)
        guard end > limited.lowerBound else { return [] }
        return inner.read(limited.lowerBound..<end)
    }
}

/// 10,240 bytes in six stretches that look nothing alike: zeros, a ramp, text, random bytes, 0xFF, and
/// bytes of every kind. The same file is built in the Python that works out the expected values.
func mapMixedFile() -> [UInt8] {
    var bytes: [UInt8] = []
    bytes.append(contentsOf: [UInt8](repeating: 0x00, count: 2048))
    for i in 0..<2048 { bytes.append(UInt8(truncatingIfNeeded: i * 3)) }
    let phrase = Array("The quick brown fox jumps over the lazy dog. ".utf8)
    for i in 0..<2048 { bytes.append(phrase[i % phrase.count]) }
    var random = BytesCheckRandom(seed: 12345)
    for _ in 0..<2048 { bytes.append(random.byte()) }
    bytes.append(contentsOf: [UInt8](repeating: 0xFF, count: 1024))
    for i in 0..<1024 { bytes.append(UInt8(truncatingIfNeeded: i * 37 + 11)) }
    return bytes
}

func mapCell(_ zero: Int = 0, _ full: Int = 0, _ text: Int = 0, _ control: Int = 0, _ high: Int = 0) -> ByteMapCell {
    ByteMapCell(classCounts: [zero, full, text, control, high])
}

func mapNear(_ a: Double, _ b: Double, _ tolerance: Double = 1e-9) -> Bool {
    abs(a - b) <= tolerance
}

// MARK: The Hilbert curve

func checkTheHilbertCurve() {
    // Order 2 is the textbook curve; checking it fixes which way up the others are.
    let textbook: [Int] = [0, 0, 1, 0, 1, 1, 0, 1, 0, 2, 0, 3, 1, 3, 1, 2, 2, 2, 2, 3, 3, 3, 3, 2, 3, 1, 2, 1, 2, 0, 3, 0]
    var textbookMatches = true
    for i in 0..<16 {
        let point = HilbertCurve.point(order: 2, index: i)
        if point.x != textbook[i * 2] || point.y != textbook[i * 2 + 1] { textbookMatches = false }
    }
    check(textbookMatches, "an order 2 curve is the textbook one: starts top left, ends top right")

    for order in 0...7 {
        let side = 1 << order
        let cells = side * side
        check(HilbertCurve.cellCount(order: order) == cells, "order \(order) has \(cells) cells")
        var seen = [Bool](repeating: false, count: cells)
        var inside = true
        var roundTrips = true
        var neverJumps = true
        var previous = HilbertCurve.point(order: order, index: 0)
        for i in 0..<cells {
            let point = HilbertCurve.point(order: order, index: i)
            guard point.x >= 0, point.x < side, point.y >= 0, point.y < side else { inside = false; continue }
            seen[point.y * side + point.x] = true
            if HilbertCurve.index(order: order, x: point.x, y: point.y) != i { roundTrips = false }
            if i > 0, abs(point.x - previous.x) + abs(point.y - previous.y) != 1 { neverJumps = false }
            previous = point
        }
        check(inside && !seen.contains(false), "order \(order): every cell of the grid is visited, once")
        check(roundTrips, "order \(order): index undoes point for every cell")
        check(neverJumps, "order \(order): each step is to the cell next door")
        let first = HilbertCurve.point(order: order, index: 0)
        let last = HilbertCurve.point(order: order, index: cells - 1)
        check(first.x == 0 && first.y == 0 && last.x == side - 1 && last.y == 0, "order \(order): from the top left to the top right")
    }

    // An aligned run of 4^m cells fills a square of 2^m, which is why a patch of the file is a patch of the picture.
    var squares = true
    for m in 1...4 {
        let run = 1 << (2 * m)
        let edge = 1 << m
        for start in stride(from: 0, to: 1 << 10, by: run) {
            var low = (x: Int.max, y: Int.max)
            var high = (x: -1, y: -1)
            for i in start..<(start + run) {
                let point = HilbertCurve.point(order: 5, index: i)
                low = (min(low.x, point.x), min(low.y, point.y))
                high = (max(high.x, point.x), max(high.y, point.y))
            }
            if high.x - low.x + 1 != edge || high.y - low.y + 1 != edge || low.x % edge != 0 || low.y % edge != 0 { squares = false }
        }
    }
    check(squares, "every aligned run of 4^m cells fills one aligned square 2^m across")

    let before = HilbertCurve.point(order: 3, index: -5)
    let past = HilbertCurve.point(order: 3, index: 1000)
    let end = HilbertCurve.point(order: 3, index: 63)
    check(before.x == 0 && before.y == 0 && past.x == end.x && past.y == end.y, "an index off either end is moved to the nearest end")
    check(HilbertCurve.index(order: 3, x: -1, y: 99) == HilbertCurve.index(order: 3, x: 0, y: 7)
          && HilbertCurve.index(order: 3, x: 99, y: -4) == HilbertCurve.index(order: 3, x: 7, y: 0), "a column or row off the grid is moved to its edge")
    check(HilbertCurve.cellCount(order: 99) == HilbertCurve.cellCount(order: HilbertCurve.maxOrder) && HilbertCurve.cellCount(order: -4) == 1, "an order is kept to what is allowed")
}
checkTheHilbertCurve()

// MARK: Kinds of byte and entropy

func checkKindsOfByteAndEntropy() {
    let table = ByteClass.table.map { String($0.rawValue) }.joined()
    check(table == "0333333332233233333333333333333322222222222222222222222222222222222222222222222222222222222222222222222222222222222222222222222344444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444444441", "every byte value is in the class the rules give it")
    check(ByteClass.of(0x00) == .zero && ByteClass.of(0xFF) == .full, "0x00 and 0xFF are kinds of their own")
    check([0x41, 0x7E, 0x20, 0x09, 0x0A, 0x0D].allSatisfy { ByteClass.of(UInt8($0)) == .text }, "letters, symbols, space, tab and line breaks are text")
    check([0x01, 0x08, 0x0B, 0x1F, 0x7F].allSatisfy { ByteClass.of(UInt8($0)) == .control }, "the other control codes, and DEL, are control codes")
    check(ByteClass.of(0x80) == .high && ByteClass.of(0xFE) == .high, "0x80 to 0xFE are the rest")
    check(ByteClass.counts(inHistogram: [Int](repeating: 1, count: 256)) == [1, 1, 98, 29, 127], "256 values, once each, split 1, 1, 98 text, 29 control, 127 other")
    check(ByteClass.counts(inHistogram: [5, 7]) == [5, 0, 0, 7, 0], "a histogram shorter than 256 counts what it has")
    check(ByteClass.counts(inHistogram: [Int](repeating: 1, count: 300)) == [1, 1, 98, 29, 127], "and one longer than 256 is read no further than 256")

    check(Entropy.shannon([UInt8](repeating: 0, count: 1000)) == 0, "a run of one value has no entropy")
    check(Entropy.shannon((0...255).map { UInt8($0) }) == 8, "all 256 values, once each, is 8 bits")
    check(mapNear(Entropy.shannon((0..<1000).map { UInt8($0 % 2) }), 1.0), "two values, equally often, is 1 bit")
    check(mapNear(Entropy.shannon([97, 97, 98]), 0.9182958340544896, 1e-12), "two of one and one of another is 0.918 bits")
    check(mapNear(Entropy.shannon((0..<40).map { UInt8($0 % 4) }), 2.0), "four values, equally often, is 2 bits")
    check(mapNear(Entropy.shannon(Array([UInt8](repeating: 0, count: 90) + [UInt8](repeating: 1, count: 10))), 0.4689955935892812, 1e-12), "nine to one is 0.469 bits")
    check(mapNear(Entropy.shannon(Array("hello, world".utf8)), 3.0220552088742, 1e-12), "a line of text, as Python works it out")
    check(Entropy.shannon([]) == 0 && Entropy.shannon(histogram: []) == 0 && Entropy.shannon(histogram: [Int](repeating: 0, count: 256)) == 0, "no bytes is 0 bits, not a crash")
    check(mapNear(Entropy.shannon(histogram: [3, 1]), Entropy.shannon([0, 0, 0, 1]), 1e-12), "a histogram and the bytes it counts agree, even one shorter than 256")
    check(mapNear(Entropy.shannon(histogram: [-5, 10, 10]), 1, 1e-12), "a count below 0 is ignored")
    check(Entropy.shannon(histogram: [Int](repeating: 7, count: 256)) == 8, "every value equally often, however often, is 8 bits")

    let corrections: [Double] = [7.17, 256, 162, 7.623659964029537, 4.1, 256, 50, 4.238070423835076, 0.0, 1000, 1, 0.0, 7.95, 4096, 256, 7.994908109793297, 2.5, 100, 20, 2.6370560288844516, 7.99, 1073741824, 256, 7.990000171310844, 7.99, 256, 256, 8.0, -1.0, 100, 5, 0.0]
    var correctionsMatch = true
    for i in stride(from: 0, to: corrections.count, by: 4) {
        let got = Entropy.corrected(bits: corrections[i], bytes: Int64(corrections[i + 1]), distinct: Int(corrections[i + 2]))
        if !mapNear(got, corrections[i + 3], 1e-12) { correctionsMatch = false }
    }
    check(correctionsMatch, "the small-sample correction adds (values seen - 1) / (2 * bytes * ln 2), up to 8")

    func reading(_ bits: Double, _ bytes: Int64 = 1_000_000, _ distinct: Int = 256) -> String {
        EntropyReading.describe(bits: bits, bytes: bytes, distinct: distinct)
    }
    let phrases = [
        "almost all one value: zeros or padding",
        "very repetitive: padding, long runs or sparse data",
        "repetitive: tables, simple data or runs",
        "text or structured data",
        "program code or dense binary data",
        "dense binary or lightly compressed data",
        "random-looking: compressed, encrypted or noise"
    ]
    check(reading(0.2) == phrases[0] && reading(1.0) == phrases[1] && reading(3.0) == phrases[2] && reading(4.5) == phrases[3], "the low bands")
    check(reading(6.0) == phrases[4] && reading(7.0) == phrases[5] && reading(7.9) == phrases[6], "the high bands")
    // Each band starts exactly where it says, with no small-sample correction to blur it (one value seen).
    let edges: [Double] = [0.5, 2.0, 3.5, 5.2, 6.8, 7.5]
    check(edges.enumerated().allSatisfy { reading($1 - 0.01, 1_000_000, 1) == phrases[$0] && reading($1, 1_000_000, 1) == phrases[$0 + 1] }, "the bands begin at 0.5, 2, 3.5, 5.2, 6.8 and 7.5 bits")
    check(reading(7.17, 256, 162) == phrases[6], "256 random bytes score about 7.2 and are still called random-looking")
    check(reading(4.1, 256, 50) == phrases[3], "256 bytes of text are still called text")
    check(reading(3, 63, 20) == "too few bytes to say" && reading(3, 0, 0) == "too few bytes to say", "a few bytes say nothing")
    var lastBand = -1
    var inOrder = true
    var bits = 0.0
    while bits <= 8.0 {
        if let band = phrases.firstIndex(of: reading(bits)) {
            if band < lastBand { inOrder = false }
            lastBand = band
        } else {
            inOrder = false
        }
        bits += 0.05
    }
    check(inOrder && lastBand == 6, "up the scale from 0 to 8 bits the words only ever say more random, and end at random")
}
checkKindsOfByteAndEntropy()

