func checkZIPContents() {
    let plain = structureBytes("")
    let streamed = structureBytes("")
    let badCRC = structureBytes("")
    let small = structureBytes("")
    let large = structureBytes("")
    let damaged = structureBytes("")
    func data(_ bytes: [UInt8], _ entry: String) -> FieldNode? {
        ZIPParser.parse(DataByteSource(bytes), context: ParseContext()).roots.first { $0.name == entry }?.resolvedChildren().first { $0.name == "Compressed data" }
    }
    for entry in ["Entry 1", "Entry 2", "Entry 3"] {
        check(data(plain, entry)?.value?.hasSuffix("CRC matches") == true, "\(entry) of an archive Python made, deflated or stored, matches its CRC: \(data(plain, entry)?.value ?? "none")")
    }
    check(data(plain, "Entry 1")?.note?.contains(" Decompressed (") == true && data(plain, "Entry 1")?.note?.contains("bytes from") == true, "the note says it was decompressed, and to how much: \(data(plain, "Entry 1")?.note ?? "")")
    check(data(streamed, "Entry 1")?.value?.hasSuffix("CRC matches") == true, "an entry whose CRC is in a data descriptor is checked against the central directory's: \(data(streamed, "Entry 1")?.value ?? "none")")
    check(data(badCRC, "Entry 1")?.value?.hasSuffix("CRC DIFFERS") == true && data(badCRC, "Entry 2")?.value?.hasSuffix("CRC matches") == true,
          "a recorded CRC one bit off differs, and only for its entry: \(data(badCRC, "Entry 1")?.value ?? "none")")
    check(data(small, "Entry 1")?.value?.hasSuffix("SIZE DIFFERS") == true && data(large, "Entry 1")?.value?.hasSuffix("SIZE DIFFERS") == true,
          "a recorded size one byte short or long is said to differ: \(data(small, "Entry 1")?.value ?? "none") \(data(large, "Entry 1")?.value ?? "none")")
    let broken = data(damaged, "Entry 1")?.value ?? "none"
    check(broken.hasSuffix("DAMAGED") || broken.hasSuffix("DIFFERS"), "compressed bytes that were changed are found out: \(broken)")
    // A streamed entry's local header with its compressed size filled in and its CRC left 0, and no central directory:
    // the 0 is not a CRC, so nothing is checked.
    let localOnly: [UInt8] = {
        let directory = Int(streamed[streamed.count - 6]) | Int(streamed[streamed.count - 5]) << 8
        var bytes = Array(streamed[0..<directory])
        for index in 0..<4 { bytes[18 + index] = streamed[directory + 20 + index] }
        return bytes
    }()
    let localData = data(localOnly, "Entry 1")
    check(localData != nil && localData?.value?.contains("CRC") == false && localData?.value?.contains("DIFFERS") == false, "a streamed entry found without the central directory is not checked against its zero CRC: \(localData?.value ?? "none")")
    let directory = Int(streamed[streamed.count - 6]) | Int(streamed[streamed.count - 5]) << 8
    let noDirectory = Array(streamed[0..<directory])
    let local = ZIPParser.parse(DataByteSource(noDirectory), context: ParseContext())
    check(streamed[6] & 8 != 0 && local.roots.contains { $0.name == "Entry 1" } && data(noDirectory, "Entry 1")?.value?.contains("CRC") != true,
          "without the central directory, a streamed entry's zero CRC is not checked")
    var entry = ZIPParser.Entry()
    entry.method = 8
    entry.crc = UInt64(CRC32.checksum(Array("hello".utf8)))
    entry.uncompressedSize = 5
    let stream = [UInt8]([0x01, 0x05, 0x00, 0xFA, 0xFF] + Array("hello".utf8))
    check(ZIPParser.checkData(DataByteSource(stream), entry: entry, dataStart: 0, dataLength: 10)?.value == "CRC matches", "a deflate stream of one stored block is checked")
    check(ZIPParser.checkData(DataByteSource(stream), entry: entry, dataStart: 0, dataLength: 10, limit: 4) == nil, "an entry bigger than the limit is not")
    entry.flags = 1
    check(ZIPParser.checkData(DataByteSource(stream), entry: entry, dataStart: 0, dataLength: 10) == nil, "nor an encrypted one")
    entry.flags = 0
    entry.method = 12
    check(ZIPParser.checkData(DataByteSource(stream), entry: entry, dataStart: 0, dataLength: 10) == nil, "nor one compressed some other way")
    entry.method = 8
    check(ZIPParser.checkData(DataByteSource(stream), entry: entry, dataStart: 0, dataLength: 11) == nil, "nor one that runs past the end of the file")
    check(ZIPParser.checkData(DataByteSource(stream + [9, 9]), entry: entry, dataStart: 0, dataLength: 12)?.note.contains("after the end of the compressed stream") == true,
          "bytes after the stream's end are said to be")
}
checkZIPContents()

func checkGIFPixels() {
    // GIFs made by Pillow and ImageMagick, each with the size and CRC-32 of its first frame's colour indices as Pillow reads them back.
    let made: [(String, String, Int, Int, UInt32)] = [
        ("1x1, 2 colours", "4749463837610100010081000082b70eee7f1a0000000000002c000000000100010000080400010404003b", 1, 1, 3523407757),
        ("7x3, 4 colours", "4749463837610700030081000039bef07ec2347f066ed08f5d2c0000000007000300000814000704001040e0408201120a109030e100010101003b", 7, 3, 158327836),
        ("31x17 noise, 16 colours", "", 31, 17, 3330319878),
        ("120x90 noise, 256 colours", "", 120, 90, 232727382),
        ("200x150 stripes, 64 colours", "", 200, 150, 3672644979),
        ("300x40 flat, 2 colours", "", 300, 40, 1789366942),
        ("magick gradient", "", 64, 48, 313178696),
        ("magick plasma", "", 90, 60, 252687167),
        ("magick text", "", 80, 30, 4090631346),
    ]
    var wrong: [String] = []
    for (name, hex, width, height, crc) in made {
        let bytes = structureBytes(hex)
        let outcome = GIFParser.parse(DataByteSource(bytes), context: ParseContext())
        guard let image = outcome.roots.first(where: { $0.name == "Image 1" }), let data = image.resolvedChildren().first(where: { $0.name == "Image data" }),
              let codeSize = image.resolvedChildren().first(where: { $0.name == "LZW minimum code size" }) else { wrong.append("\(name): no image data"); continue }
        if data.value?.hasSuffix("decodes to \(width * height) pixels") != true || data.kind == .problem { wrong.append("\(name): \(data.value ?? "none") \(data.note ?? "")") }
        var indices: [UInt8] = []
        let check = GIFParser.decodeLZW(DataByteSource(bytes), codeSize: Int(bytes[Int(codeSize.offset)]), from: data.offset, end: data.offset + data.length) { indices.append($0) }
        if indices.count != width * height || CRC32.checksum(indices) != crc || !check.sawEnd || check.badCodeAt != nil { wrong.append("\(name): \(indices.count) indices, CRC \(CRC32.checksum(indices)) not \(crc), \(check)") }
        if !structureProblems(outcome.roots, fileLength: Int64(bytes.count)).isEmpty { wrong.append("\(name): unsound") }
    }
    check(wrong.isEmpty, "the first frame of GIFs Pillow and ImageMagick made decodes to the colour indices Pillow reads: \(wrong.prefix(2))")
    let animation = structureBytes("")
    let interlaced = structureBytes("")
    let animated = GIFParser.parse(DataByteSource(animation), context: ParseContext())
    check(animated.summary?.contains("3 images, 0.40 s a loop, loops forever") == true, "an animation says how long one loop is: \(animated.summary ?? "none")")
    var frames: [String] = []
    for number in 1...3 {
        let data = animated.roots.first { $0.name == "Image \(number)" }?.resolvedChildren().first { $0.name == "Image data" }
        frames.append(data?.value?.components(separatedBy: " · ").last ?? "none")
    }
    check(Set(frames).count == 1 && frames[0].hasPrefix("decodes to"), "every frame is decoded: \(frames)")
    let interlacedData = GIFParser.parse(DataByteSource(interlaced), context: ParseContext()).roots.first { $0.name == "Image 1" }?.resolvedChildren().first { $0.name == "Image data" }
    check(interlacedData?.value?.hasSuffix("decodes to 1480 pixels") == true, "an interlaced image has as many pixels: \(interlacedData?.value ?? "none")")
    let codeSizeAt = 13 + 12 + 10
    let ok = structureBytes("474946383961020002008100000000000000000000000000002c00000000020002000002028c53003b")
    let short = structureBytes("474946383961020002008100000000000000000000000000002c00000000020002000002024c01003b")
    let long = structureBytes("474946383961020002008100000000000000000000000000002c00000000020002000002038c1305003b")
    let bad = structureBytes("474946383961020002008100000000000000000000000000002c0000000002000200000202cc0b003b")
    let noEnd = structureBytes("474946383961020002008100000000000000000000000000002c0000000002000200000202641c003b")
    let tooHigh = structureBytes("474946383961020002008000000000000000002c00000000020002000002029c53003b")
    let atTable = structureBytes("474946383961020002008000000000000000002c00000000020002000002029453003b")
    let badSize = structureBytes("474946383961020002008100000000000000000000000000002c00000000020002000009028c53003b")
    func verdict(_ bytes: [UInt8]) -> FieldNode? {
        GIFParser.parse(DataByteSource(bytes), context: ParseContext()).roots.first { $0.name == "Image 1" }?.resolvedChildren().first { $0.name == "Image data" }
    }
    check(verdict(ok)?.value?.hasSuffix("decodes to 4 pixels") == true && verdict(ok)?.kind == .bytes, "a hand-made stream with a code that is being made decodes: \(verdict(ok)?.value ?? "none") \(verdict(ok)?.note ?? "")")
    var hand: [UInt8] = []
    _ = GIFParser.decodeLZW(DataByteSource(ok), codeSize: 2, from: Int64(codeSizeAt + 1), end: Int64(ok.count - 1)) { hand.append($0) }
    check(hand == [1, 1, 1, 1], "to the indices it was made from: \(hand)")
    check(verdict(short)?.value?.hasSuffix("PIXEL COUNT DIFFERS") == true && verdict(short)?.note?.contains("3 fewer") == true && verdict(short)?.kind == .problem, "too few pixels: \(verdict(short)?.note ?? "none")")
    check(verdict(long)?.value?.hasSuffix("PIXEL COUNT DIFFERS") == true && verdict(long)?.note?.contains("1 more") == true, "too many: \(verdict(long)?.note ?? "none")")
    check(verdict(bad)?.value?.hasSuffix("DAMAGED") == true && verdict(bad)?.note?.contains("after 1 pixels") == true, "a code not yet in the table: \(verdict(bad)?.note ?? "none")")
    check(verdict(noEnd)?.value?.hasSuffix("decodes to 4 pixels") == true && verdict(noEnd)?.note?.contains("no end-of-information code") == true, "no end code is said, and is not a fault: \(verdict(noEnd)?.note ?? "none")")
    check(verdict(tooHigh)?.value?.hasSuffix("COLOURS OUTSIDE THE TABLE") == true && verdict(tooHigh)?.note?.contains("uses colour 3") == true, "an index past the colour table: \(verdict(tooHigh)?.note ?? "none")")
    check(verdict(atTable)?.value?.hasSuffix("COLOURS OUTSIDE THE TABLE") == true && verdict(atTable)?.note?.contains("uses colour 2") == true, "an index one past the last colour: \(verdict(atTable)?.note ?? "none")")
    check(verdict(badSize)?.value?.hasSuffix("BAD CODE SIZE") == true, "a minimum code size of 9: \(verdict(badSize)?.value ?? "none")")
    // Damaged and cut GIFs: decoding never traps and the tree stays sound.
    var random = BytesCheckRandom(seed: 77)
    var unsound: [String] = []
    let samples = made.map { structureBytes($0.1) } + [animation, interlaced]
    for round in 0..<400 {
        var bytes = samples[random.below(samples.count)]
        for _ in 0..<(1 + random.below(4)) { bytes[13 + random.below(bytes.count - 13)] ^= UInt8(1 << random.below(8)) }
        if round % 3 == 0 { bytes = Array(bytes.prefix(14 + random.below(bytes.count - 14))) }
        let outcome = GIFParser.parse(DataByteSource(bytes), context: ParseContext())
        let problems = structureProblems(outcome.roots, fileLength: Int64(bytes.count))
        if !problems.isEmpty { unsound.append("round \(round): \(problems[0])") }
    }
    check(unsound.isEmpty, "400 damaged GIFs decode without trapping and give sound trees: \(unsound.prefix(2))")
}
checkGIFPixels()

